7	import path from 'node:path';
8	import { isEmpty, fileExists } from './fileUtils.js';
9	import { isSubpath, resolveToRealPath } from './paths.js';
10	
11	/**
12	 * Standard error messages for the plan approval workflow.
13	 * Shared between backend tools and CLI UI for consistency.
14	 */
15	export const PlanErrorMessages = {
16	  PATH_ACCESS_DENIED: (planPath: string, plansDir: string) =>
17	    `Access denied: plan path (${planPath}) must be within the designated plans directory (${plansDir}).`,
18	  FILE_NOT_FOUND: (path: string) =>
19	    `Plan file does not exist: ${path}. You must create the plan file before requesting approval.`,
20	  FILE_EMPTY:
21	    'Plan file is empty. You must write content to the plan file before requesting approval.',
22	  READ_FAILURE: (detail: string) => `Failed to read plan file: ${detail}`,
23	} as const;
24	
25	/**
26	 * Validates a plan file path for safety (traversal) and existence.
27	 * @param planPath The untrusted path to the plan file.
28	 * @param plansDir The authorized project plans directory.
29	 * @param targetDir The current working directory (project root).
30	 * @returns An error message if validation fails, or null if successful.
31	 */
32	export async function validatePlanPath(
33	  planPath: string,
34	  plansDir: string,
35	): Promise<string | null> {
36	  const safeFilename = path.basename(planPath);
37	  const resolvedPath = path.join(plansDir, safeFilename);
38	  const realPath = resolveToRealPath(resolvedPath);
39	  const realPlansDir = resolveToRealPath(plansDir);
40	
41	  if (!isSubpath(realPlansDir, realPath)) {
42	    return PlanErrorMessages.PATH_ACCESS_DENIED(planPath, realPlansDir);
43	  }
44	
45	  if (!(await fileExists(resolvedPath))) {
46	    return PlanErrorMessages.FILE_NOT_FOUND(planPath);
47	  }
48	
49	  return null;
50	}
51	
52	/**
53	 * Validates that a plan file has non-empty content.
54	 * @param planPath The path to the plan file.
55	 * @returns An error message if the file is empty or unreadable, or null if successful.
56	 */
57	export async function validatePlanContent(
58	  planPath: string,
59	): Promise<string | null> {
60	  try {
61	    if (await isEmpty(planPath)) {
62	      return PlanErrorMessages.FILE_EMPTY;
63	    }
64	    return null;
65	  } catch (err) {
66	    const message = err instanceof Error ? err.message : String(err);
67	    return PlanErrorMessages.READ_FAILURE(message);
68	  }
69	}
