49	/**
50	 * Shortens a path string if it exceeds maxLen, prioritizing the start and end segments.
51	 * Example: /path/to/a/very/long/file.txt -> /path/.../long/file.txt
52	 */
53	export function shortenPath(filePath: string, maxLen: number = 35): string {
54	  if (filePath.length <= maxLen) {
55	    return filePath;
56	  }
57	
58	  const simpleTruncate = () => {
59	    const keepLen = Math.floor((maxLen - 3) / 2);
60	    if (keepLen <= 0) {
61	      return filePath.substring(0, maxLen - 3) + '...';
62	    }
63	    const start = filePath.substring(0, keepLen);
64	    const end = filePath.substring(filePath.length - keepLen);
65	    return `${start}...${end}`;
66	  };
67	
68	  type TruncateMode = 'start' | 'end' | 'center';
69	
70	  const truncateComponent = (
71	    component: string,
72	    targetLength: number,
73	    mode: TruncateMode,
74	  ): string => {
75	    if (component.length <= targetLength) {
76	      return component;
77	    }
78	
79	    if (targetLength <= 0) {
80	      return '';
81	    }
82	
83	    if (targetLength <= 3) {
84	      if (mode === 'end') {
85	        return component.slice(-targetLength);
86	      }
87	      return component.slice(0, targetLength);
88	    }
89	
90	    if (mode === 'start') {
91	      return `${component.slice(0, targetLength - 3)}...`;
92	    }
93	
94	    if (mode === 'end') {
95	      return `...${component.slice(component.length - (targetLength - 3))}`;
96	    }
97	
98	    const front = Math.ceil((targetLength - 3) / 2);
99	    const back = targetLength - 3 - front;
100	    return `${component.slice(0, front)}...${component.slice(
101	      component.length - back,
102	    )}`;
103	  };
104	
105	  const parsedPath = path.parse(filePath);
106	  const root = parsedPath.root;
107	  const separator = path.sep;
108	
109	  // Get segments of the path *after* the root
110	  const relativePath = filePath.substring(root.length);
111	  const segments = relativePath.split(separator).filter((s) => s !== ''); // Filter out empty segments
112	
113	  // Handle cases with no segments after root (e.g., "/", "C:\") or only one segment
114	  if (segments.length <= 1) {
115	    // Fall back to simple start/end truncation for very short paths or single segments
116	    return simpleTruncate();
117	  }
118	
119	  const firstDir = segments[0];
120	  const lastSegment = segments[segments.length - 1];
121	  const startComponent = root + firstDir;
122	
123	  const endPartSegments = [lastSegment];
124	  let endPartLength = lastSegment.length;
125	
126	  // Iterate backwards through the middle segments
127	  for (let i = segments.length - 2; i > 0; i--) {
128	    const segment = segments[i];
129	    const newLength =
130	      startComponent.length +
131	      separator.length +
132	      3 + // for "..."
133	      separator.length +
134	      endPartLength +
135	      separator.length +
136	      segment.length;
137	
138	    if (newLength <= maxLen) {
139	      endPartSegments.unshift(segment);
140	      endPartLength += separator.length + segment.length;
141	    } else {
142	      break;
143	    }
144	  }
145	
146	  const components = [firstDir, ...endPartSegments];
147	  const componentModes: TruncateMode[] = components.map((_, index) => {
148	    if (index === 0) {
149	      return 'start';
150	    }
151	    if (index === components.length - 1) {
152	      return 'end';
153	    }
154	    return 'center';
155	  });
156	
157	  const separatorsCount = endPartSegments.length + 1;
158	  const fixedLen = root.length + separatorsCount * separator.length + 3; // ellipsis length
159	  const availableForComponents = maxLen - fixedLen;
160	
161	  const trailingFallback = () => {
162	    const ellipsisTail = `...${separator}${lastSegment}`;
163	    if (ellipsisTail.length <= maxLen) {
164	      return ellipsisTail;
165	    }
166	
167	    if (root) {
168	      const rootEllipsisTail = `${root}...${separator}${lastSegment}`;
169	      if (rootEllipsisTail.length <= maxLen) {
170	        return rootEllipsisTail;
171	      }
172	    }
173	
174	    if (root && `${root}${lastSegment}`.length <= maxLen) {
175	      return `${root}${lastSegment}`;
176	    }
177	
178	    if (lastSegment.length <= maxLen) {
179	      return lastSegment;
180	    }
181	
182	    // As a final resort (e.g., last segment itself exceeds maxLen), fall back to simple truncation.
183	    return simpleTruncate();
184	  };
185	
186	  if (availableForComponents <= 0) {
187	    return trailingFallback();
188	  }
189	
190	  const minLengths = components.map((component, index) => {
191	    if (index === 0) {
192	      return Math.min(component.length, 1);
193	    }
194	    if (index === components.length - 1) {
195	      return component.length; // Never truncate the last segment when possible.
196	    }
197	    return Math.min(component.length, 1);
198	  });
199	
200	  const minTotal = minLengths.reduce((sum, len) => sum + len, 0);
201	  if (availableForComponents < minTotal) {
202	    return trailingFallback();
203	  }
204	
205	  const budgets = components.map((component) => component.length);
206	  let currentTotal = budgets.reduce((sum, len) => sum + len, 0);
207	
208	  const pickIndexToReduce = () => {
209	    let bestIndex = -1;
210	    let bestScore = -Infinity;
211	    for (let i = 0; i < budgets.length; i++) {
212	      if (budgets[i] <= minLengths[i]) {
213	        continue;
214	      }
215	      const isLast = i === budgets.length - 1;
216	      const score = (isLast ? 0 : 1_000_000) + budgets[i];
217	      if (score > bestScore) {
218	        bestScore = score;
219	        bestIndex = i;
220	      }
221	    }
222	    return bestIndex;
223	  };
224	
225	  while (currentTotal > availableForComponents) {
226	    const index = pickIndexToReduce();
227	    if (index === -1) {
228	      return trailingFallback();
229	    }
230	    budgets[index]--;
231	    currentTotal--;
232	  }
233	
234	  const truncatedComponents = components.map((component, index) =>
235	    truncateComponent(component, budgets[index], componentModes[index]),
236	  );
237	
238	  const truncatedFirst = truncatedComponents[0];
239	  const truncatedEnd = truncatedComponents.slice(1).join(separator);
240	  const result = `${root}${truncatedFirst}${separator}...${separator}${truncatedEnd}`;
241	
242	  if (result.length > maxLen) {
243	    return trailingFallback();
244	  }
245	
246	  return result;
247	}
